import {connected} from './region.js?v=jail-overcrowding-1';
import {occupancy} from './utilities.js?v=jail-overcrowding-1';
// Prima pp.163–165: zone populations, border routes and developed port tiles.
export const ECONOMIC_BASE={commercial:25000,industrial:70000};
export const ECONOMIC_RELIEF={road:{commercial:12000,industrial:12000},highway:{commercial:20000,industrial:14000},rail:{commercial:0,industrial:25000},subway:{commercial:25000,industrial:0},airport:{commercial:500,industrial:100},seaport:{commercial:100,industrial:250}};
export function economicCaps(c){const sources=[];
 for(const con of c.region.connections){const relief=ECONOMIC_RELIEF[con.kind];if(!relief||con.kind==='seaport'||!connected(c,con)||(['road','highway'].includes(con.kind)&&c.finance.roadCondition<=20))continue;sources.push({name:con.kind+' connection · '+con.side,...relief});}
 for(const p of c.stats.facilityPlots||[])if(p.operating){const relief=ECONOMIC_RELIEF[p.type];sources.push({name:p.type+' · '+p.ids.length+' developed tiles',commercial:relief.commercial*p.ids.length,industrial:relief.industrial*p.ids.length});}
 return Object.fromEntries(Object.entries(ECONOMIC_BASE).map(([sector,base])=>{const entries=sources.filter(s=>s[sector]>0).map(s=>({name:s.name,amount:s[sector]})),relief=entries.reduce((sum,s)=>sum+s.amount,0),population=c.stats[sector==='commercial'?'commercialJobs':'industrialJobs'],limit=base+relief;return[sector,{base,relief,limit,population,remaining:Math.max(0,limit-population),sources:entries}];}));
}
export function economicGrowthFits(c,t,members){const cap=c.stats.economicCaps?.[t.type];if(!cap||t.industry==='farm')return true;return members.length*(occupancy(t.level+1)-occupancy(t.level))*(t.type==='commercial'?6:12)<=cap.remaining;}
export function economicCapReport(c){if(!c.stats.economicCaps)return'';const fmt=n=>n.toLocaleString('en-US');return Object.entries(c.stats.economicCaps).map(([sector,cap])=>`<details id="${sector}CapReport"><summary>${sector==='commercial'?'Commercial':'Industrial'} growth capacity · ${fmt(cap.population)} / ${fmt(cap.limit)} jobs</summary><p>Base ${fmt(cap.base)} · outside connections and operating ports add ${fmt(cap.relief)} · room for ${fmt(cap.remaining)} jobs.</p>${cap.sources.length?`<ul>${cap.sources.map(s=>`<li>${s.name}: +${fmt(s.amount)}</li>`).join('')}</ul>`:'<p>No qualifying outside routes or ports.</p>'}<p>Connect ${sector==='industrial'?'a road, highway or railway':'a road, highway or subway'} to a neighbor, or develop supplied airport/seaport zones. Capacity is citywide; individual districts still need transport, demand and services. Existing jobs are not removed just for exceeding capacity.</p></details>`).join('');}
